/**
 * Ark Tiles – Delivery Date API client
 *
 * Wraps the Rules API endpoints and cart metafield save calls.
 * The Rules API base URL is read from the window-level config injected
 * by BigCommerce Stencil (window.checkoutConfig) or falls back to a
 * same-origin path.
 */

import { type AvailabilityRequest, type AvailabilityResponse, type DeliverySelection } from './types';

const RULES_API_BASE =
    (typeof window !== 'undefined' && (window as any).checkoutConfig?.deliveryRulesApiBase) ||
    '/api/delivery';

async function post<TReq, TRes>(path: string, body: TReq): Promise<TRes> {
    const response = await fetch(`${RULES_API_BASE}${path}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
    });

    if (!response.ok) {
        throw new Error(`Delivery API error ${response.status}: ${await response.text()}`);
    }

    return response.json() as Promise<TRes>;
}

/** Fetch available delivery dates for the current basket + postcode. */
export async function fetchAvailability(request: AvailabilityRequest): Promise<AvailabilityResponse> {
    return post<AvailabilityRequest, AvailabilityResponse>('/availability', request);
}

/** Persist the customer's selected delivery date to a cart metafield. */
export async function saveDeliverySelection(
    checkoutId: string,
    selection: DeliverySelection,
): Promise<void> {
    await post('/selection', { checkoutId, ...selection });
}

/** Final validation call immediately before order placement. */
export async function validateDeliverySelection(
    checkoutId: string,
    selection: DeliverySelection,
    request: AvailabilityRequest,
): Promise<{ valid: boolean; reason?: string }> {
    return post('/validate', { checkoutId, selection, request });
}
