/**
 * Ark Tiles – DeliveryDateSelector component
 *
 * Shows a month-view calendar for pallet deliveries only.
 * Available dates are enabled; weekends, bank holidays and dates before the
 * earliest lead-time date are disabled.
 */

import { type Cart, type Consignment } from '@bigcommerce/checkout-sdk';
import { useFormikContext } from 'formik';
import React, { type FunctionComponent, useCallback, useEffect, useRef, useState } from 'react';

import { useCheckout } from '@bigcommerce/checkout/contexts';

import { fetchAvailability as fetchAvailabilityFromApi, saveDeliverySelection } from './deliveryApi';
import './DeliveryDateSelector.scss';
import { FREE_SHIPPING_THRESHOLD, getAvailableDates, resolveBasketClass, resolveZone } from './ruleEngine';
import {
    type AvailabilityRequest,
    type AvailabilityResponse,
    type CartLineItem,
    type DeliverySelection,
    type ShippingGroup,
} from './types';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const RULE_VERSION = 'v1';
const PALLET_GROUPS: ShippingGroup[] = ['pallet_standard', 'pallet_next_day'];
const DAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const DELIVERY_DATE_TAG = 'Preferred delivery date:';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function mapCartItems(cart: Cart): CartLineItem[] {
    return (cart?.lineItems?.physicalItems ?? []).map((item) => {
        const attrs: Record<string, string> = {};
        (item.options ?? []).forEach((opt: { name: string; value: string }) => {
            attrs[opt.name] = opt.value;
        });

        const shippingGroup: ShippingGroup =
            (attrs['delivery_shipping_group'] as ShippingGroup) ?? 'parcel_standard';

        return {
            productId: item.productId,
            sku: item.sku,
            quantity: item.quantity,
            shippingGroup,
            specialOrder: attrs['delivery_special_order'] === 'true',
            leadTimeMinDays: parseInt(attrs['delivery_lead_time_min'] ?? '1', 10),
            leadTimeMaxDays: parseInt(attrs['delivery_lead_time_max'] ?? '3', 10),
        };
    });
}

function formatShortDate(dateStr: string): string {
    if (!dateStr) return '';
    const d = new Date(dateStr + 'T00:00:00Z');
    return d.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });
}

/** Injects/replaces the delivery date tag line at the top of the order comment. */
function injectDateIntoComment(existing: string, dateStr: string): string {
    const tagLine = `${DELIVERY_DATE_TAG} ${formatShortDate(dateStr)}`;
    // Strip any existing tag line first
    const stripped = existing.replace(/^Preferred delivery date:.*(\n)?/m, '').trim();
    return stripped ? `${tagLine}\n${stripped}` : tagLine;
}

/** Returns YYYY-MM for a given year+month (0-indexed month). */
function toYearMonth(year: number, month: number): string {
    return `${year}-${String(month + 1).padStart(2, '0')}`;
}

/** Returns YYYY-MM-DD for a given year, month (0-indexed), day. */
function toDateStr(year: number, month: number, day: number): string {
    return `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

/** How many days in a given month. */
function daysInMonth(year: number, month: number): number {
    return new Date(year, month + 1, 0).getDate();
}

/**
 * Day-of-week index for the 1st of the month in Mon-first grid (Mon=0…Sun=6).
 * JS getDay() returns Sun=0…Sat=6, so we remap.
 */
function firstDayOffset(year: number, month: number): number {
    const jsDay = new Date(year, month, 1).getDay(); // 0=Sun
    return (jsDay + 6) % 7; // Mon=0
}

// ---------------------------------------------------------------------------
// Calendar sub-component
// ---------------------------------------------------------------------------

interface CalendarProps {
    availableDates: Set<string>;
    earliestDate: string;
    selectedDate: string;
    isSaving: boolean;
    onSelect(dateStr: string): void;
}

const Calendar: FunctionComponent<CalendarProps> = ({
    availableDates,
    earliestDate,
    selectedDate,
    isSaving,
    onSelect,
}) => {
    const initialYear = earliestDate ? parseInt(earliestDate.slice(0, 4), 10) : new Date().getFullYear();
    const initialMonth = earliestDate ? parseInt(earliestDate.slice(5, 7), 10) - 1 : new Date().getMonth();

    const [viewYear, setViewYear] = useState(initialYear);
    const [viewMonth, setViewMonth] = useState(initialMonth);

    const today = toDateStr(new Date().getFullYear(), new Date().getMonth(), new Date().getDate());
    const days = daysInMonth(viewYear, viewMonth);
    const offset = firstDayOffset(viewYear, viewMonth);

    // Build sorted list of available dates to determine the last month we should allow navigating to
    const sortedDates = Array.from(availableDates).sort();
    const lastAvailableDate = sortedDates[sortedDates.length - 1] ?? earliestDate;
    const lastYear = lastAvailableDate ? parseInt(lastAvailableDate.slice(0, 4), 10) : viewYear;
    const lastMonth = lastAvailableDate ? parseInt(lastAvailableDate.slice(5, 7), 10) - 1 : viewMonth;

    const canGoPrev = toYearMonth(viewYear, viewMonth) > toYearMonth(initialYear, initialMonth);
    const canGoNext = toYearMonth(viewYear, viewMonth) < toYearMonth(lastYear, lastMonth);

    const prevMonth = () => {
        if (viewMonth === 0) { setViewYear(y => y - 1); setViewMonth(11); }
        else { setViewMonth(m => m - 1); }
    };

    const nextMonth = () => {
        if (viewMonth === 11) { setViewYear(y => y + 1); setViewMonth(0); }
        else { setViewMonth(m => m + 1); }
    };

    const monthLabel = new Date(viewYear, viewMonth, 1).toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });

    // Build the grid cells: offset blanks + day numbers
    const cells: Array<number | null> = [
        ...Array(offset).fill(null),
        ...Array.from({ length: days }, (_, i) => i + 1),
    ];

    return (
        <div className="deliveryDateSelector-calendar">
            <div className="deliveryDateSelector-calNav">
                <button
                    className="deliveryDateSelector-calNavBtn"
                    disabled={!canGoPrev}
                    onClick={prevMonth}
                    type="button"
                >‹</button>
                <span className="deliveryDateSelector-calMonth">{monthLabel}</span>
                <button
                    className="deliveryDateSelector-calNavBtn"
                    disabled={!canGoNext}
                    onClick={nextMonth}
                    type="button"
                >›</button>
            </div>

            <div className="deliveryDateSelector-calGrid">
                {DAY_LABELS.map((d) => (
                    <div className="deliveryDateSelector-calDayLabel" key={d}>{d}</div>
                ))}

                {cells.map((day, idx) => {
                    if (day === null) {
                        return <div className="deliveryDateSelector-calCell is-empty" key={`empty-${idx}`} />;
                    }

                    const dateStr = toDateStr(viewYear, viewMonth, day);
                    const isAvailable = availableDates.has(dateStr);
                    const isSelected = dateStr === selectedDate;
                    const isToday = dateStr === today;

                    const classes = [
                        'deliveryDateSelector-calCell',
                        isAvailable ? 'is-available' : 'is-disabled',
                        isSelected ? 'is-selected' : '',
                        isToday ? 'is-today' : '',
                    ].filter(Boolean).join(' ');

                    return (
                        <button
                            className={classes}
                            disabled={!isAvailable || isSaving}
                            key={dateStr}
                            onClick={() => onSelect(dateStr)}
                            title={isAvailable ? formatShortDate(dateStr) : undefined}
                            type="button"
                        >
                            {day}
                        </button>
                    );
                })}
            </div>
        </div>
    );
};

// ---------------------------------------------------------------------------
// Main component
// ---------------------------------------------------------------------------

export interface DeliveryDateSelectorProps {
    consignments: Consignment[];
}

interface State {
    availability: AvailabilityResponse | null;
    isLoading: boolean;
    error: string | null;
    selectedDate: string;
    isSaving: boolean;
}

const QUICKSTEP_RE = /quick.?step/i;
const NO_CALENDAR_METHODS = /coventry\s+showroom|click.?(and|&)?.?collect/i;

function stripDateFromComment(comment: string): string {
    return comment.replace(/^Preferred delivery date:.*(\n)?/m, '').trim();
}

const DeliveryDateSelector: FunctionComponent<DeliveryDateSelectorProps> = ({ consignments }) => {
    const {
        checkoutState: { data: { getCart, getCheckout } },
    } = useCheckout();

    // All hooks must be called unconditionally before any early return
    const { values: formValues, setFieldValue } = useFormikContext<{ orderComment: string }>();

    const cart = getCart();
    const checkout = getCheckout();
    const checkoutId = checkout?.id ?? '';
    const storedKey = `ark-delivery-date-${checkoutId}`;

    const firstConsignment = consignments[0];
    const postcode = firstConsignment?.shippingAddress?.postalCode ?? '';
    const selectedShippingOptionId = firstConsignment?.selectedShippingOption?.id ?? '';
    const selectedShippingOptionDescription = firstConsignment?.selectedShippingOption?.description ?? '';

    // Determine what kind of delivery is selected
    const cartItems = cart ? mapCartItems(cart) : [];
    const basketClass = resolveBasketClass(cartItems);
    const cartHasQuickstep = (cart?.lineItems?.physicalItems ?? []).some(
        (item) => QUICKSTEP_RE.test(item.name) || QUICKSTEP_RE.test(item.brand ?? ''),
    );
    const isQuickstepMethod = /quickstep\s+shipping/i.test(selectedShippingOptionDescription);
    const isQuickstepDelivery = cartHasQuickstep && isQuickstepMethod;
    const shippingMethodIsPallet = /pallet/i.test(selectedShippingOptionDescription);
    const isPalletBasket = PALLET_GROUPS.includes(basketClass) || shippingMethodIsPallet;
    const selectedShippingCost = firstConsignment?.selectedShippingOption?.cost ?? -1;
    const isFreeDelivery = selectedShippingCost === 0 && (cart?.cartAmount ?? 0) > FREE_SHIPPING_THRESHOLD;
    const isNonCalendarMethod = NO_CALENDAR_METHODS.test(selectedShippingOptionDescription);

    const shouldShowCalendar =
        !!postcode &&
        !!selectedShippingOptionId &&
        !isNonCalendarMethod &&
        (isPalletBasket || isQuickstepDelivery || isFreeDelivery);

    const effectiveBasketClass: ShippingGroup =
        isQuickstepDelivery
            ? 'quickstep'
            : isFreeDelivery
                ? 'free_delivery'
                : PALLET_GROUPS.includes(basketClass)
                    ? basketClass
                    : /next.?day/i.test(selectedShippingOptionDescription)
                        ? 'pallet_next_day'
                        : 'pallet_standard';

    const storedDate = typeof window !== 'undefined' ? (localStorage.getItem(storedKey) ?? '') : '';

    const [state, setState] = useState<State>({
        availability: null,
        isLoading: false,
        error: null,
        selectedDate: storedDate,
        isSaving: false,
    });

    const prevFetchKey = useRef<string>('');

    // When a non-calendar method is selected, clear the stored date and order comment
    useEffect(() => {
        if (!shouldShowCalendar && selectedShippingOptionId) {
            localStorage.removeItem(storedKey);
            setState((prev) => ({ ...prev, selectedDate: '', availability: null }));
            prevFetchKey.current = '';
            const current = formValues.orderComment ?? '';
            if (current.includes(DELIVERY_DATE_TAG)) {
                void setFieldValue('orderComment', stripDateFromComment(current));
            }
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [selectedShippingOptionId, shouldShowCalendar]);

    const selectDate = useCallback(async (dateStr: string, availableDates: string[]) => {
        if (!dateStr || !availableDates.includes(dateStr)) return;
        setState((prev) => ({ ...prev, selectedDate: dateStr, isSaving: true }));
        localStorage.setItem(storedKey, dateStr);

        const updatedComment = injectDateIntoComment(formValues.orderComment ?? '', dateStr);
        void setFieldValue('orderComment', updatedComment);

        const selection: DeliverySelection = {
            requestedDeliveryDate: dateStr,
            basketClass: effectiveBasketClass,
            deliveryZone: resolveZone(postcode),
            leadTimeMinDays: availableDates.indexOf(dateStr) + 1,
            leadTimeMaxDays: availableDates.indexOf(dateStr) + 2,
            ruleVersion: RULE_VERSION,
        };
        try {
            await saveDeliverySelection(checkoutId, selection);
        } catch {
            // Non-fatal
        } finally {
            setState((prev) => ({ ...prev, isSaving: false }));
        }
    }, [checkoutId, postcode, effectiveBasketClass, storedKey, formValues.orderComment, setFieldValue]);

    const fetchAvailability = useCallback(async () => {
        if (!shouldShowCalendar) return;
        const fetchKey = [postcode, selectedShippingOptionId, effectiveBasketClass, cartItems.map((i) => `${i.productId}x${i.quantity}`).join(',')].join('|');
        if (fetchKey === prevFetchKey.current) return;
        prevFetchKey.current = fetchKey;

        setState((prev) => ({ ...prev, isLoading: true, error: null }));

        const request: AvailabilityRequest = {
            postcode,
            shippingOptionId: selectedShippingOptionId,
            cart: cartItems.map((i) => ({ ...i, shippingGroup: effectiveBasketClass })),
            now: new Date().toISOString(),
        };

        try {
            let result: AvailabilityResponse;
            try {
                result = await fetchAvailabilityFromApi(request);
            } catch {
                result = getAvailableDates(request);
            }

            // Restore stored date if still valid, otherwise pre-select first available
            const currentStored = localStorage.getItem(storedKey) ?? '';
            const dateToSelect = result.availableDates.includes(currentStored)
                ? currentStored
                : (result.availableDates[0] ?? '');

            setState((prev) => ({ ...prev, availability: result, isLoading: false, selectedDate: dateToSelect }));

            if (dateToSelect) {
                await selectDate(dateToSelect, result.availableDates);
            }
        } catch {
            setState((prev) => ({ ...prev, isLoading: false, error: 'Unable to load delivery dates. Please try again or contact us.' }));
        }
    }, [shouldShowCalendar, cart, postcode, selectedShippingOptionId, effectiveBasketClass, storedKey]);

    useEffect(() => { void fetchAvailability(); }, [fetchAvailability]);

    // Early return after all hooks
    if (!shouldShowCalendar) return null;

    const { availability, isLoading, error, selectedDate, isSaving } = state;
    const isQuickstepCalendar = effectiveBasketClass === 'quickstep';
    const calendarTitle = isQuickstepCalendar
        ? 'Choose your preferred delivery date'
        : 'Choose your preferred pallet delivery date';
    const unavailableMsg = isQuickstepCalendar
        ? 'Delivery is not available to this postcode. Please contact us.'
        : 'Pallet delivery is not available to this postcode. Please contact us.';

    // ---------------------------------------------------------------------------
    // Render
    // ---------------------------------------------------------------------------
    return (
        <div className="deliveryDateSelector">
            <p className="deliveryDateSelector-title">{calendarTitle}</p>

            {isLoading && <p className="deliveryDateSelector-loading">Loading available dates…</p>}
            {error && <p className="deliveryDateSelector-error">{error}</p>}

            {availability && !isLoading && (
                <>
                    {availability.messages.map((msg, i) => (
                        <p className="deliveryDateSelector-message" key={i}>{msg}</p>
                    ))}

                    {availability.availableDates.length === 0 ? (
                        <p className="deliveryDateSelector-unavailable">
                            {unavailableMsg}
                        </p>
                    ) : (
                        <Calendar
                            availableDates={new Set(availability.availableDates)}
                            earliestDate={availability.earliestDeliveryDate}
                            isSaving={isSaving}
                            onSelect={(d) => void selectDate(d, availability.availableDates)}
                            selectedDate={selectedDate}
                        />
                    )}

                    {selectedDate && (
                        <p className="deliveryDateSelector-selected">
                            ✓ Preferred delivery date: {formatShortDate(selectedDate)}
                        </p>
                    )}
                </>
            )}
        </div>
    );
};

export default DeliveryDateSelector;

