/**
 * Ark Tiles – Delivery Date Rule Engine
 *
 * Implements the basket priority rule, postcode zone resolver,
 * cut-off logic, and working-day date generator described in the
 * delivery.prompt.md specification.
 */

import { isBankHoliday } from './bankHolidays';
import {
    type AvailabilityRequest,
    type AvailabilityResponse,
    type CartLineItem,
    type DeliveryZone,
    type ServiceRule,
    type ShippingGroup,
} from './types';

// ---------------------------------------------------------------------------
// Configuration constants — edit these to change business rules
// ---------------------------------------------------------------------------

/** Order subtotal (£) above which free shipping qualifies for a delivery date calendar. */
export const FREE_SHIPPING_THRESHOLD = 500;

// ---------------------------------------------------------------------------
// 1. Basket priority resolver
// ---------------------------------------------------------------------------

const PRIORITY_ORDER: ShippingGroup[] = [
    'special_order',
    'pallet_next_day',
    'pallet_standard',
    'quickstep',
    'free_delivery',
    'parcel_next_day',
    'parcel_standard',
    'sample_post',
    'click_collect',
];

export function resolveBasketClass(lines: CartLineItem[]): ShippingGroup {
    const groups = new Set(lines.map((l) => l.shippingGroup));

    for (const group of PRIORITY_ORDER) {
        if (groups.has(group)) {
            return group;
        }
    }

    return 'click_collect';
}

// ---------------------------------------------------------------------------
// 2. Postcode zone resolver
// ---------------------------------------------------------------------------

/**
 * Maps a UK postcode prefix to a delivery zone.
 * Postcode areas are matched by prefix in priority order (most specific first).
 */
export function resolveZone(postcode: string): DeliveryZone {
    const upper = postcode.trim().toUpperCase().replace(/\s+/g, '');
    const area = upper.match(/^([A-Z]{1,2})/)?.[1] ?? '';

    // Channel Islands – excluded
    if (upper.startsWith('JE')) return 'jersey';
    if (upper.startsWith('GY')) return 'guernsey';

    // Shetland & Outer Hebrides
    if (/^HS/.test(area) || /^ZE/.test(area)) return 'shetland_outer_hebrides';

    // Isle of Man
    if (upper.startsWith('IM')) return 'isle_of_man';

    // Scottish Highlands & Islands
    // BT = Northern Ireland (treat as excluded), IV, KW, PA20–PA78, PH15–PH50, AB31–AB56, DD8–DD9, FK17–FK21, KY9, KY10
    const highlandAreas = ['IV', 'KW', 'HS', 'ZE'];
    if (highlandAreas.includes(area)) return 'scottish_highlands';

    // Rough Highland range checks for mixed-area postcodes
    if (area === 'PA') {
        const districtMatch = upper.match(/^PA(\d+)/);
        const district = districtMatch ? parseInt(districtMatch[1], 10) : 0;
        if (district >= 20 && district <= 78) return 'scottish_highlands';
    }
    if (area === 'PH') {
        const districtMatch = upper.match(/^PH(\d+)/);
        const district = districtMatch ? parseInt(districtMatch[1], 10) : 0;
        if (district >= 15 && district <= 50) return 'scottish_highlands';
    }
    if (area === 'AB') {
        const districtMatch = upper.match(/^AB(\d+)/);
        const district = districtMatch ? parseInt(districtMatch[1], 10) : 0;
        if (district >= 31 && district <= 56) return 'scottish_highlands';
    }

    // Scotland (non-Highland)
    const scotlandAreas = ['AB', 'DD', 'DG', 'EH', 'FK', 'G', 'KA', 'KY', 'KW', 'ML', 'PA', 'PH', 'TD'];
    if (scotlandAreas.includes(area)) return 'scotland_excl_highlands';

    // Wales
    const walesAreas = ['CF', 'CH', 'LD', 'LL', 'NP', 'SA', 'SY'];
    // SY covers Shropshire too, but the overlap with Wales is close enough for zone purposes
    if (walesAreas.includes(area) || (area === 'HR' && false)) return 'wales';

    // London
    const londonAreas = ['E', 'EC', 'N', 'NW', 'SE', 'SW', 'W', 'WC', 'BR', 'CR', 'DA', 'EN', 'HA', 'IG', 'KT', 'RM', 'SM', 'TW', 'UB', 'WD'];
    if (londonAreas.includes(area)) return 'london';

    // Default: mainland England (excluding London)
    return 'mainland_england_excl_london';
}

