export function getServiceRule(basketClass: ShippingGroup, zone: DeliveryZone): ServiceRule {
    return SERVICE_RULES[basketClass][zone] ?? ZONE_UNAVAILABLE;
}

// ---------------------------------------------------------------------------
// 4. Cut-off logic (12pm dispatch rule)
// ---------------------------------------------------------------------------

/** Returns the dispatch date string (YYYY-MM-DD) based on current time vs 12pm cut-off */
export function resolveDispatchDate(nowIso: string): string {
    const now = new Date(nowIso);
    const cutoffHour = 12;

    // If before 12pm on a working day, same-day dispatch
    const isBeforeCutoff = now.getHours() < cutoffHour;
    const dayOfWeek = now.getDay(); // 0=Sun, 6=Sat
    const dateStr = toDateString(now);

    if (isBeforeCutoff && dayOfWeek !== 0 && dayOfWeek !== 6 && !isBankHoliday(dateStr)) {
        return dateStr;
    }

    // Otherwise move to next working day
    return nextWorkingDay(now);
}

// ---------------------------------------------------------------------------
// 5. Date utilities
// ---------------------------------------------------------------------------

function toDateString(date: Date): string {
    return date.toISOString().slice(0, 10);
}

function addDays(dateStr: string, days: number): Date {
    const d = new Date(dateStr + 'T00:00:00Z');
    d.setUTCDate(d.getUTCDate() + days);
    return d;
}

function isWeekend(date: Date): boolean {
    const day = date.getUTCDay();
    return day === 0 || day === 6;
}

function nextWorkingDay(from: Date): string {
    const d = new Date(from);
    d.setUTCDate(d.getUTCDate() + 1);
    while (isWeekend(d) || isBankHoliday(toDateString(d))) {
        d.setUTCDate(d.getUTCDate() + 1);
    }
    return toDateString(d);
}

function addWorkingDays(fromStr: string, days: number): string {
    let d = new Date(fromStr + 'T00:00:00Z');
    let added = 0;
    while (added < days) {
        d.setUTCDate(d.getUTCDate() + 1);
        if (!isWeekend(d) && !isBankHoliday(toDateString(d))) {
            added++;
        }
    }
    return toDateString(d);
}

// ---------------------------------------------------------------------------
// 6. Main availability generator
// ---------------------------------------------------------------------------

const DATE_WINDOW_BUFFER = 30; // Generate this many extra calendar days past maxDays

export function getAvailableDates(input: AvailabilityRequest): AvailabilityResponse {
    const basketClass = resolveBasketClass(input.cart);
    const zone = resolveZone(input.postcode);
    const rule = getServiceRule(basketClass, zone);

    if (!rule.zoneAllowed) {
        return {
            zone,
            basketClass,
            earliestDeliveryDate: '',
            latestEstimatedDeliveryDate: '',
            availableDates: [],
            messages: rule.messages,
        };
    }

    // click_collect: no calendar needed
    if (basketClass === 'click_collect') {
        return {
            zone,
            basketClass,
            earliestDeliveryDate: toDateString(new Date(input.now)),
            latestEstimatedDeliveryDate: toDateString(new Date(input.now)),
            availableDates: [],
            messages: rule.messages,
        };
    }

    const dispatchDateStr = resolveDispatchDate(input.now);

    const earliestDeliveryStr = addWorkingDays(dispatchDateStr, rule.minDays);
    const latestEstimatedStr = addWorkingDays(dispatchDateStr, rule.maxDays);

    // Generate candidate dates from earliest up to latest + buffer
    const windowEnd = addDays(latestEstimatedStr, DATE_WINDOW_BUFFER);
    const availableDates: string[] = [];

    let current = new Date(earliestDeliveryStr + 'T00:00:00Z');
    while (current <= windowEnd) {
        const dateStr = toDateString(current);
        if (!isWeekend(current) && !isBankHoliday(dateStr)) {
            availableDates.push(dateStr);
        }
        current.setUTCDate(current.getUTCDate() + 1);
    }

    return {
        zone,
        basketClass,
        earliestDeliveryDate: earliestDeliveryStr,
        latestEstimatedDeliveryDate: latestEstimatedStr,
        availableDates,
        messages: rule.messages,
    };
}
